import{_ as a,c as t,o,ag as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1791311600000}'),d={name:"zh-CN/guide/introduction.md"};function i(l,e,n,c,h,s){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><h2 id="关于-nplyr" tabindex="-1">关于 nPlyr <a class="header-anchor" href="#关于-nplyr" aria-label="Permalink to &quot;关于 nPlyr&quot;">​</a></h2><p><strong>nPlyr</strong> 是一款面向 <strong>macOS</strong> 与 <strong>iOS / iPadOS</strong> 的原生视频播放器。它构建于 Apple 的 <a href="https://developer.apple.com/av-foundation/" target="_blank" rel="noreferrer">AVFoundation</a>（<code>AVPlayer</code>）之上——应用内部<strong>没有任何外部二进制</strong>。在播放器的基础之上，它还加入了两项让它超越普通播放器的能力：</p><ul><li>一个<strong>内置媒体嗅探器</strong>（Chrome 风格的多标签浏览器，可从任意网页抓取视频直链），以及</li><li>一个 <strong>hikerView 兼容的小程序运行时</strong>，运行社区规则，让应用能够浏览并解析第三方视频源。</li></ul><p>这一组合有时被称为集&quot;播放器 + 嗅探器 + 小程序运行时&quot;于一身。</p><h2 id="三大支柱" tabindex="-1">三大支柱 <a class="header-anchor" href="#三大支柱" aria-label="Permalink to &quot;三大支柱&quot;">​</a></h2><h3 id="_1-原生播放器" tabindex="-1">1. 原生播放器 <a class="header-anchor" href="#_1-原生播放器" aria-label="Permalink to &quot;1. 原生播放器&quot;">​</a></h3><p>macOS 与 iOS 共用一套播放内核。它能播放 HLS（<code>m3u8</code>）、<code>MP4</code>、<code>MOV</code>、<code>M4V</code>、<code>FLV</code>、<code>TS</code> 以及任何 <code>AVPlayer</code> 可解码的容器，并支持：</p><ul><li>字幕（外部 <code>.srt</code> / <code>.vtt</code> / 内嵌）</li><li>多音轨</li><li>倍速控制</li><li>画中画</li><li>AirPlay，以及（macOS 上）DLNA 投放</li></ul><p>参见 <a href="/zh-CN/guide/player.html">播放器</a>。</p><h3 id="_2-嗅探浏览器" tabindex="-1">2. 嗅探浏览器 <a class="header-anchor" href="#_2-嗅探浏览器" aria-label="Permalink to &quot;2. 嗅探浏览器&quot;">​</a></h3><p>nPlyr 内置一个真正的 <code>WKWebView</code>，拥有多个 Chrome 风格的标签。每个页面都会被注入媒体探测脚本；当页面请求 <code>m3u8</code> / <code>mp4</code> / <code>flv</code> / <code>ts</code> 媒体时，该链接与其请求头会一并出现在结果抽屉中，你可以直接发送给播放器或下载器。</p><p>参见 <a href="/zh-CN/guide/browser.html">浏览器与嗅探器</a>。</p><h3 id="_3-小程序运行时" tabindex="-1">3. 小程序运行时 <a class="header-anchor" href="#_3-小程序运行时" aria-label="Permalink to &quot;3. 小程序运行时&quot;">​</a></h3><p>nPlyr 原生重实现了 <strong>hikerView 小程序契约</strong>：</p><ul><li>规则 DSL（<code>pdfh</code> / <code>pdfa</code> / <code>pd</code> 选择器、<code>setResult</code>、<code>lazyRule</code>、<code>$.rule</code> 等），</li><li>规则用于调用宿主功能的 <code>fy_bridge_app</code>（<code>fba</code>）JavaScript 桥（播放、fetch、解析、存储变量），</li><li><code>hiker://</code> 伪协议路由。</li></ul><p>因此，现有的 hikerView 社区规则与小程序可以直接在 nPlyr 中运行。由于原始引擎是 Android/Java（Rhino），<strong>部分 Java 特有的行为未能完全兼容</strong>——这一点在<a href="/zh-CN/guide/miniapp-compatibility.html">兼容性</a>页面中有详细说明。</p><h2 id="系统需求" tabindex="-1">系统需求 <a class="header-anchor" href="#系统需求" aria-label="Permalink to &quot;系统需求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>最低版本</th><th>说明</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 14 Sonoma</td><td>针对 Apple Silicon（M 系列）优化；支持 Intel</td></tr><tr><td>iOS</td><td>iOS 16</td><td>iPhone</td></tr><tr><td>iPadOS</td><td>iPadOS 16</td><td>iPad</td></tr></tbody></table><ul><li><strong>内存</strong>：最低 4 GB RAM，大型 HLS 播放列表建议 8 GB。</li><li><strong>存储</strong>：安装约需 60 MB，外加下载媒体所占空间。</li><li><strong>网络</strong>：流媒体、嗅探与小程序源均需要网络。</li></ul><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h2><p>应用界面已翻译为 <strong>25 种语言</strong>，并在首次启动时跟随系统语言。本文档站点提供英文、简体中文、繁體中文、日本語、Deutsch、Español 与 Français。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>在你的 Mac 或 iPhone 上<a href="/zh-CN/guide/installation.html">安装</a> nPlyr。</li><li>了解<a href="/zh-CN/guide/player.html">播放器</a>基础。</li><li>使用<a href="/zh-CN/guide/browser.html">浏览器与嗅探器</a>抓取视频流。</li><li>通过<a href="/zh-CN/guide/miniapps.html">小程序</a>探索社区资源。</li></ol>',24)])])}const m=a(d,[["render",i]]);export{u as __pageData,m as default};
